package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.*;import java.time.*;
@Entity@Table(name="spms_final_rating",uniqueConstraints=@UniqueConstraint(name="uk_spms_final_rating_revision",columnNames={"agency_id","rating_case_id","revision_no"}))public class PerformanceFinalRating extends RspAuditedEntity{@Column(name="rating_case_id",nullable=false,length=36)private String ratingCaseId;@Column(name="revision_no",nullable=false)private int revisionNo;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(name="source_assessment_id",nullable=false,length=36)private String sourceAssessmentId;@Column(name="calibration_case_id",length=36)private String calibrationCaseId;@Column(name="raw_score",nullable=false,precision=19,scale=8)private BigDecimal rawScore;@Column(name="rounded_score",nullable=false,precision=19,scale=6)private BigDecimal roundedScore;@Column(name="rating_band_id",nullable=false,length=36)private String ratingBandId;@Column(name="rating_label",nullable=false,length=200)private String ratingLabel;@Column(name="calculation_fingerprint",nullable=false,length=64)private String calculationFingerprint;@Column(name="finalized_by",nullable=false,length=100)private String finalizedBy;@Column(name="finalized_at",nullable=false)private Instant finalizedAt;protected PerformanceFinalRating(){}public PerformanceFinalRating(String a,String c,String calibration,PerformanceRatingAssessment assessment,String actor,Instant at){this(a,c,1,null,calibration,assessment,actor,at);}public PerformanceFinalRating(String a,String c,int revision,String supersedes,String calibration,PerformanceRatingAssessment assessment,String actor,Instant at){super(a);ratingCaseId=requiredText(c,"ratingCaseId");if(revision<1)throw new IllegalArgumentException("revisionNo must be positive");revisionNo=revision;supersedesId=optionalText(supersedes);sourceAssessmentId=assessment.getId();calibrationCaseId=optionalText(calibration);rawScore=assessment.getRawScore();roundedScore=assessment.getRoundedScore();ratingBandId=assessment.getRatingBandId();ratingLabel=assessment.getRatingLabel();calculationFingerprint=assessment.getCalculationFingerprint();finalizedBy=requiredText(actor,"actor");finalizedAt=at;}public String getRatingCaseId(){return ratingCaseId;}public int getRevisionNo(){return revisionNo;}public String getSupersedesId(){return supersedesId;}public String getSourceAssessmentId(){return sourceAssessmentId;}public String getCalibrationCaseId(){return calibrationCaseId;}public BigDecimal getRawScore(){return rawScore;}public BigDecimal getRoundedScore(){return roundedScore;}public String getRatingBandId(){return ratingBandId;}public String getRatingLabel(){return ratingLabel;}public String getCalculationFingerprint(){return calculationFingerprint;}public String getFinalizedBy(){return finalizedBy;}public Instant getFinalizedAt(){return finalizedAt;}}
